#include "syrk.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C: logical size i x j
	// data layout proto: first apply j_vec, then i_vec
	// (final physical layout is determined by Noarr; we keep it unchanged
	//  to preserve the original memory layout and fair benchmarking)
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);

	// A: logical size i x k
	// layout proto kept identical to the original for the same reasons
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A) {
	// C: i x j, length(i) = N, length(j) = N
	// A: i x k, length(i) = N, length(k) = M
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// Precompute lengths once; they are constant for the whole array
	const auto n_len = A | get_length<'i'>(); // N
	const auto m_len = A | get_length<'k'>(); // M

	// A[i][k] = ( (i * k + 1) % n ) / n;
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// C[i][j] = ( (i * j + 2) % m ) / m;
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
//
// BLAS SYRK:
//   C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// Optimizations vs original:
//  - Split the operation into two passes:
//      1) Scale the lower triangle of C by beta
//      2) Accumulate alpha * A * A^T into the same triangle
//    This preserves, for every (i,j), the exact order of operations
//    (first scaling by beta, then all additions), while allowing us
//    to organize the loops for better clarity.
//  - Hoist A(i,k) out of the inner j-loop: for a fixed (i,k) we load
//    A(i,k) once and reuse it for all j, which reduces memory traffic
//    and arithmetic.
//  - Avoid repeated extraction of indices when they are constant in
//    an inner loop (e.g. i is constant inside all loops under for_dims<'i'>()).
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// 1) Scale the lower triangle of C by beta: C[i][j] *= beta, j <= i
	// ------------------------------------------------------------------
	traverser(C).template for_dims<'i'>([&](auto trav_i) {
		// 'i' is fixed inside this lambda; reuse its value
		const auto i = get_index<'i'>(trav_i.state());

		// Only 'j' remains to iterate in this traverser
		trav_i.for_each([&](auto state) {
			const auto j = get_index<'j'>(state);

			if (j <= i) {
				C[state] *= beta;
			}
		});
	});

	// ------------------------------------------------------------------
	// 2) SYRK update: C := C + alpha * A * A^T on the lower triangle
	//
	//    For each row i and column j (j <= i):
	//        C[i,j] += alpha * sum_k A[i,k] * A[j,k]
	//
	//    We structure the loops as:
	//        for i
	//          for k
	//            load a_ik = A[i,k] once
	//            for j
	//              if (j <= i) accumulate using a_ik and A[j,k]
	//
	//    This preserves the per-element operation order of the original
	//    kernel while reducing redundant loads of A[i,k].
	// ------------------------------------------------------------------
	traverser(C, A).template for_dims<'i'>([&](auto trav_i) {
		// Fixed row index for this slice
		const auto i = get_index<'i'>(trav_i.state());

		// Iterate over k for the current row i
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed; only 'j' is left to iterate

			// Load A(i,k) once per (i,k) pair
			const num_t a_ik = A[trav_ik];

			// Now sweep j for this fixed (i,k)
			trav_ik.for_each([&](auto state) {
				const auto j = get_index<'j'>(state);

				if (j <= i) {
					// Build a state where index 'i' is replaced by 'j'
					// to access A[j][k]. Other indices (j,k) remain unchanged.
					auto state_jk = noarr::update_index<'i'>(state, [=](auto /*unused*/) { return j; });

					C[state] += alpha * a_ik * A[state_jk];
				}
			});
		});
	});

	#pragma endscop
}

