		auto state_i = trav_i.state();
		const std::size_t i = get_index<'i'>(state_i);

		// Only visit j in [0, i] for this row:
		//   start = 0, length = i + 1
		auto trav_lower = trav_i.order(noarr::slice<'j'>(std::size_t(0), i + 1));

		trav_lower.for_each([&](auto state_ij) {
			C[state_ij] *= beta;
		});
	});

