			const num_t a_ik = A[state_ik];
			const num_t alpha_a_ik = alpha * a_ik;

			// Restrict j to the lower triangle for this i: j in [0, i]
			auto trav_ik_lower = trav_ik.order(noarr::slice<'j'>(std::size_t(0), i + 1));

			trav_ik_lower.for_each([&](auto state) {
				const std::size_t j = get_index<'j'>(state);

				// A[j][k]: build a minimal state for A with ('i' = j, 'k' = k)
				const num_t a_jk = A[noarr::idx<'i', 'k'>(j, k)];

