		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
//
// BLAS SYRK (lower triangle):
//   C := alpha * A * A^T + beta * C
//
// A is N x M (i x k)
// C is N x N (i x j), only j <= i updated
//
// Optimizations compared to the original version:
//   * Avoids a separate pass that multiplies C by beta when M > 0:
//       - instead, applies beta once per C(i,j) in the first k-iteration
//   * Moves the load of A[i,k] and the multiplication by alpha outside
//     the inner j‑loop (one alpha-multiply per (i,k), not per (i,j,k))
//   * Avoids update_index for A[j,k] and uses an explicitly built state
//     noarr::idx<'i','k'>(j,k) instead
//   * Preserves the original traversal order in terms of logical indices:
//       i (row) -> k -> j
//     which gives:
//       - contiguous access over k in A
//       - contiguous access over j in C
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	// Length of the k-dimension (M). We use this only to handle the
	// degenerate case M == 0 correctly.
	const auto m_len = A | get_length<'k'>();

#pragma scop
	if (m_len == 0) {
		// Degenerate case: A has zero columns, so SYRK reduces to:
		//   C := beta * C   on the lower triangle.
		//
		// We perform exactly the same work as the original kernel in this
		// situation, but only touch C (A is empty anyway).
		traverser(C).template for_dims<'i'>([=](auto trav_i) {
			const auto i_state = trav_i.state();
			const auto i_idx   = get_index<'i'>(i_state);

			// Iterate j in the inner/contiguous dimension of C
			trav_i.template for_each<'j'>([=](auto state_ij) {
				const auto j_idx = get_index<'j'>(state_ij);

				if (j_idx <= i_idx) {
					C[state_ij] *= beta;
				}
			});
		});
	} else {
		// General case: M > 0.
		//
		// We combine the "beta * C" scaling with the main accumulation.
		// For each pair (i,j) in the lower triangle, we:
		//   - scale C(i,j) by beta once when k == 0
		//   - for all k, accumulate alpha * A(i,k) * A(j,k)
		//
		// Loop structure (expressed with traverser + for_dims/for_each):
		//   for i in rows:
		//     for k in columns of A:
		//       temp = alpha * A(i,k);
		//       for j in row of C:
		//         if (j <= i):
		//           if (k == 0)  C(i,j) *= beta;
		//           C(i,j) += temp * A(j,k);
		traverser(C, A).template for_dims<'i'>([=](auto trav_i) {
			const auto i_state = trav_i.state();
			const auto i_idx   = get_index<'i'>(i_state);

			// For each column k of A for the current row i
			trav_i.template for_dims<'k'>([=](auto trav_ik) {
				const auto state_ik = trav_ik.state();
				const auto k_idx    = get_index<'k'>(state_ik);

				// A(i,k) is reused for all j in this (i,k) pair,
				// so load it once and pre-multiply by alpha.
				const num_t a_ik = A[state_ik];
				const num_t temp = alpha * a_ik;

				// Now sweep j along the contiguous j-dimension of C.
				trav_ik.template for_each<'j'>([=](auto state) {
					const auto j_idx = get_index<'j'>(state);

					// Only lower triangular part is updated
					if (j_idx <= i_idx) {
						// Apply beta exactly once per C(i,j), on the first k
						if (k_idx == 0) {
							C[state] *= beta;
						}

						// Access A(j,k): its logical indices are (i=j, k)
						// Note that A ignores 'j' as such, it uses 'i' and 'k'.
						const num_t a_jk = A[noarr::idx<'i', 'k'>(j_idx, k_idx)];

						C[state] += temp * a_jk;
					}
				});
			});
		});
	}
#pragma endscop
