[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	// N = length of the 'i' dimension (rows of C and A)
	const std::size_t n = C | get_length<'i'>();

	#pragma scop
	// -------------------------------------------------------------------------
	// 1) Scale the lower triangle of C by beta: C[i,j] *= beta for j <= i
	// -------------------------------------------------------------------------
	//
	// We iterate C column-by-column (j-major). For each column j, we only visit
	// rows i in [j, N), which corresponds exactly to the lower triangular part.
	traverser(C).template for_dims<'j'>([&](auto trav_j) {
		// Get the current column index j from the traverser state
		const std::size_t j = get_index<'j'>(trav_j.state());

		// Restrict iteration in this column to i in [j, N).
		// This is equivalent to: for (i = j; i < N; ++i)
		auto lower_trav = trav_j.order(noarr::slice<'i'>(j, n - j));

		lower_trav.for_each([&](auto state) {
			// state contains 'i' and 'j'; only the lower triangle is visited
			C[state] *= beta;
		});
	});

	// -------------------------------------------------------------------------
	// 2) Rank-k update: C[i,j] += alpha * sum_k A[i,k] * A[j,k]  for j <= i
	// -------------------------------------------------------------------------
	//
	// Outer loop over columns j of C (and rows j of A).
	// Then for each column j, we loop over all k, precompute ajk_alpha = alpha*A[j,k],
	// and finally update all i >= j:
	//
	//   for j
	//     for k
	//       ajk_alpha = alpha * A[j,k]
	//       for i = j..N-1
	//         C[i,j] += ajk_alpha * A[i,k]
	//
	// Again, i is the innermost dimension here, matching the physical layout of
	// both C and A (i is inner for both), which maximizes spatial locality.
	traverser(C, A).template for_dims<'j'>([&](auto trav_j) {
		// Current column index in C (and row index in A)
		const std::size_t j = get_index<'j'>(trav_j.state());

		// Loop over k for this fixed j
		trav_j.template for_dims<'k'>([&](auto trav_k) {
			const std::size_t k = get_index<'k'>(trav_k.state());

			// A[j,k] is shared across all i >= j for this (j,k) pair.
			// Build an index state with i = j, current k, and no j (A ignores 'j').
			num_t a_jk = A[noarr::idx<'i', 'k'>(j, k)];

			// Pre-scale by alpha once per (j,k), instead of once per (i,j,k).
			const num_t ajk_alpha = alpha * a_jk;

			// For this fixed (j,k), update all i in [j, N).
			auto lower_trav = trav_k.order(noarr::slice<'i'>(j, n - j));

			lower_trav.for_each([&](auto state) {
				// state has dimensions 'i', 'j', 'k'; for A, 'j' is ignored.
				num_t a_ik = A[state];      // A[i,k]
				C[state] += ajk_alpha * a_ik;
			});
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t alpha;
	num_t beta;

	// set lengths for each structure
	auto set_lengths_C = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);
	auto set_lengths_A = noarr::set_length<'i'>(n) ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths_C);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths_A);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syrk(alpha, beta, C.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' to print C in i-major order
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
