	// C: i x j  (logical), stored as j (outer) x i (inner)
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A: i x k  (logical), stored as k (outer) x i (inner)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A) {
	// C: i x j, length(i) = N, length(j) = N
	// A: i x k, length(i) = N, length(k) = M
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// Hoist invariant lengths out of the traversals
	const std::size_t n_len = A | get_length<'i'>(); // N
	const std::size_t m_len = A | get_length<'k'>(); // M

	// A[i][k] = ( (i * k + 1) % n ) / n;
	traverser(A).for_each([&](auto state) {
		const std::size_t i = get_index<'i'>(state);
		const std::size_t k = get_index<'k'>(state);

		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// C[i][j] = ( (i * j + 2) % m ) / m;
	// Note: we intentionally use A's second dimension length (M), as in the original.
	traverser(C).for_each([&](auto state) {
		const std::size_t i = get_index<'i'>(state);
		const std::size_t j = get_index<'j'>(state);

		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
//
// BLAS SYRK:
//   C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// Optimizations relative to the original version:
//
//  - We remove the inner `if (j <= i)` tests by restricting the traverser
//    to j in [0, i] using noarr::slice in `order(...)`. This preserves
//    semantics but avoids branches in the innermost loops.
//
//  - For each (i, k) pair we load A[i][k] once and keep it in a scalar
//    (`a_ik`), instead of reloading it for every j. This reduces memory
//    traffic on A's row i and improves cache usage and vectorization
//    opportunities.
//
//  - We keep using Noarr traversers for all loop nests and index the bags
//    only via states, as required.
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop
	// Traverse over i, sharing the same i for both C and A
	traverser(C, A).template for_dims<'i'>([&](auto trav_i) {
		// Extract the current row index i once per outer iteration
		const auto state_i = trav_i.state();
		const std::size_t i = get_index<'i'>(state_i);

		// ---------------------------------------------------------------------
		// 1) Scale the lower triangle C[i][j] for 0 <= j <= i by beta
		// ---------------------------------------------------------------------

		// Limit traversal over j to the lower triangle part (0 .. i)
		auto trav_scale = trav_i.order(noarr::slice<'j'>(0, i + 1));

		trav_scale.for_each([&](auto state) {
			// state carries indices (i, j); j is already in [0, i]
			C[state] *= beta;
		});

		// ---------------------------------------------------------------------
		// 2) Rank-k update:
		//    For each k, accumulate alpha * A[i][k] * A[j][k] into C[i][j]
		//    for 0 <= j <= i.
		// ---------------------------------------------------------------------
		trav_i.template for_dims<'k'>([&](auto trav_k) {
			// state_ik has i and k fixed (j is not fixed yet)
			const auto state_ik = trav_k.state();
			const num_t a_ik = A[state_ik]; // A[i][k], loaded once per (i, k)

			// For this (i, k), traverse all j in [0, i]
			auto trav_j = trav_k.order(noarr::slice<'j'>(0, i + 1));

			trav_j.for_each([&](auto state) {
				// state now has indices (i, j, k) with j in [0, i]
				const std::size_t j = get_index<'j'>(state);
				const std::size_t k = get_index<'k'>(state);

				// Build a minimal state for A[j][k].
				// This is semantically equivalent to the original
				//   update_index<'i'>(state, j),
				// but works directly with the dimensions that A uses.
				auto state_jk = noarr::idx<'i', 'k'>(j, k);
				const num_t a_jk = A[state_jk];

				// C[i][j] += alpha * A[i][k] * A[j][k]
				C[state] += alpha * a_ik * a_jk;
			});
		});
	});
	#pragma endscop
}

